1	<script lang="ts">
2		/**
3		 * Expenses Page
4		 *
5		 * Implements expense categorization feature defined in:
6		 * specs/specifications/expense-categorization.md
7		 * specs/specifications/expense-date-filter.md
8		 *
9		 * Traceable to:
10		 * - #{#exp1a} - Expenses Tab Navigation (IMPLEMENTED)
11		 * - #{#exp1b} - Expenses derived from receipts (IMPLEMENTED)
12		 * - #{#exp9a} - Expense table layout with sorting and selection (IMPLEMENTED)
13		 * - #{#exp6a} - Uncategorized queue view (IMPLEMENTED)
14		 * - #{#exp7a} - Category filter and analytics (IMPLEMENTED)
15		 * - #{#exr1a} - Click expense row to open receipt edit modal (IMPLEMENTED)
16		 * - #{#exr1b} - Integrate existing ReceiptEditModal component (IMPLEMENTED)
17		 * - #{#exr2a} - Make expense rows clickable (IMPLEMENTED)
18		 * - #{#exr2b} - Preserve expenses state after edit (IMPLEMENTED)
19		 * - #{#exp1a} - CSV Export Button (IMPLEMENTED)
20		 * - #{#exp1b} - Respect Current Date Filter (IMPLEMENTED)
21		 * - #{#exp4b} - Integration with Expenses Page (IMPLEMENTED)
22		 * - #{#edf1a} - Expenses View URL Date Filter Integration (IMPLEMENTED)
23		 * - #{#edf4a} - URL Parameter Validation (IMPLEMENTED)
24		 *
25		 * Future enhancements will include:
26		 * - #{#exp2a} - Category assignment UI (partial implementation with CategoryDropdown)
27		 * - #{#exp6b} - Bulk category assignment (UI ready, backend needed)
28		 */
29	
30		import { onMount, untrack } from 'svelte';
31		import { page } from '$app/stores';
32		import { goto, replaceState } from '$app/navigation';
33		import { resolve } from '$app/paths';
34		import { supabase } from '$lib/supabaseClient';
35		import { getSignedReceiptUrl } from '$lib/utils/signedUrl';
36		import { ExpenseService, type Expense } from '$lib/services/ExpenseService';
37		import { CategoryService } from '$lib/services/CategoryService';
38		import { ReceiptService } from '$lib/services/ReceiptService';
39		import { CSVExportService } from '$lib/services/CSVExportService';
40		import { PDFExportService } from '$lib/services/PDFExportService';
41		import { getValidDate } from '$lib/utils/dateValidation';
42		import { Datepicker } from 'flowbite-svelte';
43		import { toDate, toISODateString, formatDate } from '$lib/utils/dateConversion';
44		import { formatCurrency, formatCurrencyWithEstimate } from '$lib/utils/formatCurrency';
45		import { getDefaultFamilyId } from '$lib/utils/familyUtils';
46		import type { Category } from '$lib/types/Category';
47		import type { Session } from '@supabase/supabase-js';
48		import type { ReceiptRow } from '$lib/models/Receipt';
49		import CategoryDropdown from '$lib/components/CategoryDropdown.svelte';
50		import ReceiptEditModal from '$lib/components/ReceiptEditModal.svelte';
51	
52		let session: Session | null = $state(null);
53		let familyId: string | null = $state(null);
54		let expenses: Expense[] = $state([]);
55		let categories: Category[] = $state([]);
56		let loading = $state(true);
57		let error: string | null = $state(null);
58		let selectedExpenses: Set<string> = $state(new Set());
59		let sortColumn: 'date' | 'merchant' | 'amount' = $state('date');
60		let sortDirection: 'asc' | 'desc' = $state('desc');
61	
62		// #{#exp6a} - Uncategorized filter state
63		let showUncategorizedOnly = $state(false);
64	
65		// #{#exp7a} - Category filter state
66		let selectedCategoryIds: string[] = $state([]);
67	
68		// #{#edf1a} - URL-based date filter state (read from query parameters)
69		let urlDateFrom = $derived(getValidDate($page.url.searchParams.get('dateFrom')));
70		let urlDateTo = $derived(getValidDate($page.url.searchParams.get('dateTo')));
71	
72		// #{#edf1a} - Temporary date filter inputs (before "Apply" is clicked)
73		let tempFilterDateFrom = $state('');
74		let tempFilterDateTo = $state('');
75	
76		// #{#edf1a} - Sync temp values when URL changes
77		$effect(() => {
78			tempFilterDateFrom = urlDateFrom;
79			tempFilterDateTo = urlDateTo;
80		});
81	
82		// #{#exr1b} - Receipt edit modal state
83		let editingReceipt: ReceiptRow | null = $state(null);
84		let editingExpense: Expense | null = $state(null);
85		let showEditModal = $state(false);
86		let isSaving = $state(false);
87		let successMessage: string | null = $state(null);
88	
89		// #{#exp1a} #{#exp3b} - CSV Export state
90		let isExporting = $state(false);
91		const csvService = new CSVExportService();
92	
93		// #{#cre1a} #{#cre4a} - PDF Export state
94		let isExportingPDF = $state(false);
95		let pdfExportProgress = $state('');
96		let pdfAbortController: AbortController | null = $state(null);
97		const pdfService = new PDFExportService();
98	
99		// Page metadata for SEO and navigation
100		export const metadata = {
101			title: 'Expenses',
102			description: 'View and categorize your expenses'
103		};
104	
105		onMount(async () => {
106			// #{#exp1a} Criterion 7: Verify authentication
107			const { data } = await supabase.auth.getSession();
108			session = data.session;
109	
110			if (!session) {
111				return;
112			}
113	
114			// Get user's default family
115			familyId = await getDefaultFamilyId();
116	
117			if (!familyId) {
118				error = 'No family found. Please contact support.';
119				return;
120			}
121	
122			// #{#exp1b} Load expenses derived from receipts
123			await loadExpenses();
124	
125			// Load family categories for dropdown
126			await loadCategories();
127	
128			// #{#vca5a} Check for auto-categorization matches on page load
129			await checkForAutoCategorizationMatches();
130		});
131	
132		/**
133		 * Load expenses from receipts using ExpenseService
134		 * #{#exp1b} - Expenses derived from receipts
135		 */
136		async function loadExpenses() {
137			if (!session?.user) return;
138	
139			try {
140				loading = true;
141				error = null;
142	
143				const expenseService = new ExpenseService(supabase);
144				expenses = await expenseService.getExpenses(session.user.id);
145			} catch (err) {
146				console.error('Error loading expenses:', err);
147				error = err instanceof Error ? err.message : 'Failed to load expenses';
148			} finally {
149				loading = false;
150			}
151		}
152	
153		/**
154		 * Check for and apply vendor rule matches to uncategorized expenses
155		 * #{#vca5a} - Batch Auto-Categorization on Page Load
156		 */
157		async function checkForAutoCategorizationMatches() {
158			if (!familyId) return;
159	
160			try {
161				const expenseService = new ExpenseService(supabase);
162	
163				// Apply all family vendor rules to current expenses
164				const totalAssigned = await expenseService.applyAllVendorRules(
165					familyId,
166					expenses
167				);
168	
169				// If any expenses were auto-assigned, reload and notify user
170				if (totalAssigned > 0) {
171					await loadExpenses();
172					showToast(
173						`Auto-categorized ${totalAssigned} expense${totalAssigned === 1 ? '' : 's'} based on vendor rules`,
174						'success'
175					);
176				}
177			} catch (err) {
178				console.error('Error checking auto-categorization:', err);
179				// Don't show error to user - this is a background operation
180			}
181		}
182	
183		/**
184		 * Load family categories for dropdown
185		 * #{#exp2a} - Category Assignment UI
186		 * #{#exp3a} - Auto-initialize default categories for new families
187		 */
188		async function loadCategories() {
189			if (!familyId) return;
190	
191			try {
192				const categoryService = new CategoryService(supabase);
193				categories = await categoryService.getFamilyCategories(familyId);
194	
195				// Auto-initialize default categories for families with no categories
196				// #{#exp3a} Requirement 2 & 3
197				if (categories.length === 0) {
198					await categoryService.createDefaultCategories(familyId);
199					categories = await categoryService.getFamilyCategories(familyId);
200				}
201			} catch (err) {
202				console.error('Error loading categories:', err);
203			}
204		}
205	
206		/**
207		 * Handle category assignment
208		 * #{#exp2a} - Category Assignment UI
209		 * #{#exp5b} - Manual Override Precedence
210		 * #{#exp5a} - Auto-create vendor rules on first categorization
211		 */
212		async function handleCategorySelect(receiptId: string, category: Category) {
213			try {
214				const expenseService = new ExpenseService(supabase);
215	
216				// 1. Assign category to this expense
217				await expenseService.assignCategory(receiptId, category.id, 'manual');
218	
219				// 2. Auto-create vendor rule if none exists
220				// Find the expense to get merchant_name
221				const expense = expenses.find((e) => e.receipt_id === receiptId);
222				if (expense && familyId) {
223					// Check if rule already exists
224					const existingRule = await expenseService.getVendorRule(
225						familyId,
226						expense.merchant_name
227					);
228	
229					// Only create rule if none exists (silent auto-creation)
230					if (!existingRule) {
231						await expenseService.createVendorRule(
232							familyId,
233							expense.merchant_name,
234							category.id
235						);
236	
237						// #{#vca1a} Apply rule to visible expenses after creating it
238						const vendorPattern = expenseService.normalizeVendor(expense.merchant_name);
239						const appliedCount = await expenseService.applyRuleToVisibleExpenses(
240							filteredExpenses,
241							vendorPattern,
242							category.id
243						);
244	
245						// #{#vca3a} Show user feedback if expenses were auto-assigned
246						if (appliedCount > 0) {
247							showToast(
248								`Applied ${category.name} to ${appliedCount} matching expense${appliedCount === 1 ? '' : 's'}`,
249								'success'
250							);
251						}
252					}
253					// If rule exists, user must click "change default" in dropdown to update it
254				}
255	
256				// 3. Reload expenses to reflect the change
257				await loadExpenses();
258			} catch (err) {
259				console.error('Error assigning category:', err);
260				error = err instanceof Error ? err.message : 'Failed to assign category';
261			}
262		}
263	
264		/**
265		 * Handle inline category creation from CategoryDropdown
266		 * #{#exp3b} - Create New Category Inline
267		 */
268		async function handleCreateNewCategory(data: { name: string; color: string | null }) {
269			try {
270				const categoryService = new CategoryService(supabase);
271				await categoryService.createCategory(familyId || '', data.name, data.color || undefined);
272				await loadCategories();
273				showToast(`Created category: ${data.name}`, 'success');
274			} catch (err) {
275				console.error('Error creating category:', err);
276				showToast(
277					err instanceof Error ? err.message : 'Failed to create category',
278					'error'
279				);
280			}
281		}
282	
283		/**
284		 * Handle vendor rule creation from CategoryDropdown
285		 * #{#vca1a} - Apply rules to visible expenses when rule is created/updated
286		 * #{#vca3a} - Show user feedback for auto-assignment
287		 */
288		async function handleVendorRuleCreated(data: { merchantName: string; categoryId: string }) {
289			try {
290				const { merchantName, categoryId } = data;
291				const expenseService = new ExpenseService(supabase);
292	
293				// Get category name for feedback
294				const category = categories.find((c) => c.id === categoryId);
295				if (!category) return;
296	
297				// Apply rule to visible expenses
298				const vendorPattern = expenseService.normalizeVendor(merchantName);
299				const appliedCount = await expenseService.applyRuleToVisibleExpenses(
300					filteredExpenses,
301					vendorPattern,
302					categoryId
303				);
304	
305				// Show user feedback
306				if (appliedCount > 0) {
307					showToast(
308						`Applied ${category.name} to ${appliedCount} matching expense${appliedCount === 1 ? '' : 's'}`,
309						'success'
310					);
311				}
312	
313				// Reload expenses to reflect the changes
314				await loadExpenses();
315			} catch (err) {
316				console.error('Error applying vendor rule:', err);
317				error = err instanceof Error ? err.message : 'Failed to apply vendor rule';
318			}
319		}
320	
321		// formatCurrency imported from $lib/utils/formatCurrency
322	
323		// formatDate imported from $lib/utils/dateConversion
324	
325		/**
326		 * Toggle expense selection for bulk operations
327		 * #{#exp9a} Criterion 1: Checkbox column for selection
328		 * #{#exp6b} Bulk category assignment
329		 */
330		function toggleExpenseSelection(receiptId: string) {
331			const newSelection = new Set(selectedExpenses);
332			if (newSelection.has(receiptId)) {
333				newSelection.delete(receiptId);
334			} else {
335				newSelection.add(receiptId);
336			}
337			selectedExpenses = newSelection;
338		}
339	
340		/**
341		 * Toggle select all expenses
342		 */
343		function toggleSelectAll() {
344			if (selectedExpenses.size === expenses.length) {
345				selectedExpenses = new Set();
346			} else {
347				selectedExpenses = new Set(expenses.map((e) => e.receipt_id));
348			}
349		}
350	
351		/**
352		 * Sort expenses by column
353		 * #{#exp9a} Criterion 6: Sortable columns
354		 */
355		function sortBy(column: 'date' | 'merchant' | 'amount') {
356			if (sortColumn === column) {
357				// Toggle direction if same column
358				sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
359			} else {
360				// New column, default to descending for date, ascending for others
361				sortColumn = column;
362				sortDirection = column === 'date' ? 'desc' : 'asc';
363			}
364		}
365	
366		/**
367		 * #{#exp6a} Criterion 2: Filter uncategorized expenses
368		 * #{#exp7a} Criterion 2 & 4: Filter by category (OR logic for multiple)
369		 * #{#edf1a} Criterion 6 & 8: Filter by date range from URL (works with category filters)
370		 */
371		let filteredExpenses = $derived(expenses.filter((expense) => {
372			// #{#edf1a} Date range filter (from URL parameters)
373			if (urlDateFrom && expense.transaction_date && expense.transaction_date < urlDateFrom) {
374				return false;
375			}
376			if (urlDateTo && expense.transaction_date && expense.transaction_date > urlDateTo) {
377				return false;
378			}
379	
380			// #{#exp6a} Uncategorized filter takes precedence
381			if (showUncategorizedOnly) {
382				return expense.category_id === null;
383			}
384	
385			// #{#exp7a} Category filter (OR logic)
386			if (selectedCategoryIds.length > 0) {
387				return expense.category_id && selectedCategoryIds.includes(expense.category_id);
388			}
389	
390			// No filters active, show all
391			return true;
392		}));
393	
394		/**
395		 * Get sorted expenses
396		 * #{#exp9a} Criterion 7: Default sort by date descending
397		 * #{#exp6a} Criterion 4: Sort uncategorized by date (newest first)
398		 */
399		let sortedExpenses = $derived([...filteredExpenses].sort((a, b) => {
400			let comparison = 0;
401	
402			switch (sortColumn) {
403				case 'date':
404					comparison =
405						new Date(a.transaction_date).getTime() - new Date(b.transaction_date).getTime();
406					break;
407				case 'merchant':
408					comparison = a.merchant_name.localeCompare(b.merchant_name);
409					break;
410				case 'amount':
411					comparison = a.total_amount - b.total_amount;
412					break;
413			}
414	
415			return sortDirection === 'asc' ? comparison : -comparison;
416		}));
417	
418		/**
419		 * #{#exp6a} Criterion 3: Count uncategorized expenses
420		 * #{#flt1a} Use filteredExpenses to reflect current filter state
421		 */
422		let uncategorizedCount = $derived(filteredExpenses.filter((e) => e.category_id === null).length);
423	
424		/**
425		 * #{#exp7a} Criterion 3: Count expenses per category
426		 * #{#flt1a} Use filteredExpenses to reflect current filter state
427		 */
428		let expenseCountByCategory = $derived(filteredExpenses.reduce(
429			(acc, expense) => {
430				const key = expense.category_id || 'uncategorized';
431				acc[key] = (acc[key] || 0) + 1;
432				return acc;
433			},
434			{} as Record<string, number>
435		));
436	
437	
438	
439		/**
440		 * #{#exp6a} Criterion 1 & 5: Toggle uncategorized filter
441		 */
442		function toggleUncategorizedFilter() {
443			showUncategorizedOnly = !showUncategorizedOnly;
444			// Clear category filter when showing uncategorized
445			if (showUncategorizedOnly) {
446				selectedCategoryIds = [];
447			}
448			updateURL();
449		}
450	
451		/**
452		 * #{#exp7a} Toggle category selection
453		 */
454		function toggleCategoryFilter(categoryId: string) {
455			if (selectedCategoryIds.includes(categoryId)) {
456				selectedCategoryIds = selectedCategoryIds.filter((id) => id !== categoryId);
457			} else {
458				selectedCategoryIds = [...selectedCategoryIds, categoryId];
459			}
460			// Clear uncategorized filter when selecting categories
461			if (selectedCategoryIds.length > 0) {
462				showUncategorizedOnly = false;
463			}
464			updateURL();
465		}
466	
467		/**
468		 * #{#exp7a} Clear all category filters
469		 */
470		function clearCategoryFilter() {
471			selectedCategoryIds = [];
472			updateURL();
473		}
474	
475		/**
476		 * #{#edf1a} Criterion 2: Apply date filters to URL
477		 */
478		function applyFilterValues(): void {
479			const params = new URLSearchParams($page.url.searchParams);
480	
481			// Update URL with date filters
482			if (tempFilterDateFrom) {
483				params.set('dateFrom', tempFilterDateFrom);
484			} else {
485				params.delete('dateFrom');
486			}
487	
488			if (tempFilterDateTo) {
489				params.set('dateTo', tempFilterDateTo);
490			} else {
491				params.delete('dateTo');
492			}
493	
494			goto(`${$page.url.pathname}?${params.toString()}`, { replaceState: true, keepFocus: true });
495		}
496	
497		/**
498		 * #{#edf1a} Criterion 3: Clear all filters (date + category)
499		 */
500		function clearClientFilters(): void {
501			// Clear URL date filters
502			const params = new URLSearchParams($page.url.searchParams);
503			params.delete('dateFrom');
504			params.delete('dateTo');
505			goto(`${$page.url.pathname}?${params.toString()}`, { replaceState: true, keepFocus: true });
506	
507			// Reset temp date filter inputs
508			tempFilterDateFrom = '';
509			tempFilterDateTo = '';
510	
511			// Clear category filters
512			showUncategorizedOnly = false;
513			selectedCategoryIds = [];
514			updateURL();
515		}
516	
517		/**
518		 * #{#exp6a} Criterion 7 & #{#exp7a}: Update URL with filter state
519		 */
520		function updateURL() {
521			const params = new URLSearchParams();
522	
523			if (showUncategorizedOnly) {
524				params.set('filter', 'uncategorized');
525			} else if (selectedCategoryIds.length > 0) {
526				params.set('category', selectedCategoryIds.join(','));
527			}
528	
529			const newURL = params.toString() ? `/expenses?${params.toString()}` : '/expenses';
530			replaceState(newURL, {});
531		}
532	
533		/**
534		 * #{#exp6a} Criterion 7 & #{#exp7a}: Restore filter state from URL on mount
535		 */
536		onMount(() => {
537			const params = new URLSearchParams(window.location.search);
538			const filter = params.get('filter');
539			const category = params.get('category');
540	
541			if (filter === 'uncategorized') {
542				showUncategorizedOnly = true;
543			} else if (category) {
544				selectedCategoryIds = category.split(',');
545			}
546		});
547	
548		/**
549		 * #{#exr1a} Open receipt edit modal when clicking expense row
550		 * #{#exr1b} Convert Expense to ReceiptRow format for modal
551		 */
552		function openReceiptEditModal(expense: Expense) {
553			editingExpense = expense;
554			editingReceipt = {
555				id: expense.receipt_id,
556				user_id: session?.user?.id || '',
557				merchant_name: expense.merchant_name,
558				transaction_date: expense.transaction_date,
559				total_amount: expense.total_amount,
560				receipt_image_path: expense.receipt_image_path,
561				tax: null,
562				currency: expense.currency,
563				exchange_rate_to_cad: expense.exchange_rate_to_cad,
564				credit_card_name: null,
565				credit_card_last_4: null,
566				created_at: new Date().toISOString(),
567				matched_transaction_id: null,
568				suspicious_date: false
569			};
570			showEditModal = true;
571		}
572	
573		/**
574		 * #{#exr1a} Handle row click events
575		 * #{#exr2a} Filter clicks on interactive elements
576		 */
577		function handleRowClick(event: MouseEvent | KeyboardEvent, expense: Expense) {
578			const target = event.target as HTMLElement;
579	
580			// Ignore clicks on interactive elements
581			if (
582				target.closest('input[type="checkbox"]') ||
583				target.closest('[data-category-dropdown]') ||
584				target.closest('a')
585			) {
586				return;
587			}
588	
589			openReceiptEditModal(expense);
590		}
591	
592		/**
593		 * #{#exr1b} Handle receipt save event from modal
594		 * #{#exr2b} Preserve state by reloading expenses without changing filters
595		 */
596		async function handleReceiptSave(updatedReceipt: ReceiptRow) {
597			isSaving = true;
598			error = null;
599	
600			try {
601				const receiptService = ReceiptService.get();
602				await receiptService.update(updatedReceipt.id, {
603					merchant_name: updatedReceipt.merchant_name,
604					transaction_date: updatedReceipt.transaction_date,
605					total_amount: updatedReceipt.total_amount,
606					tax: updatedReceipt.tax,
607					currency: updatedReceipt.currency,
608					exchange_rate_to_cad: updatedReceipt.exchange_rate_to_cad,
609					credit_card_name: updatedReceipt.credit_card_name,
610					credit_card_last_4: updatedReceipt.credit_card_last_4,
611					receipt_image_path: updatedReceipt.receipt_image_path,
612					matched_transaction_id: updatedReceipt.matched_transaction_id,
613					suspicious_date: updatedReceipt.suspicious_date
614				});
615	
616				showEditModal = false;
617				editingReceipt = null;
618				editingExpense = null;
619	
620				// #{#exr2b} Reload expenses to show updated data
621				await loadExpenses();
622	
623				// Show success message
624				successMessage = 'Receipt updated successfully';
625				setTimeout(() => {
626					successMessage = null;
627				}, 3000);
628			} catch (err) {
629				error = err instanceof Error ? err.message : 'Failed to update receipt';
630			} finally {
631				isSaving = false;
632			}
633		}
634	
635		/**
636		 * #{#exr1b} Handle modal close event
637		 */
638		function handleModalClose() {
639			showEditModal = false;
640			editingReceipt = null;
641			editingExpense = null;
642			error = null;
643		}
644	
645		/**
646		 * #{#exp1a} #{#exp4b} Handle CSV export
647		 * #{#exp1b} Respects current filter (exports filteredExpenses)
648		 * #{#exp3b} Shows loading state and feedback
649		 * #{#edf2a} CSV export respects date filters and includes date range in filename
