1	/**
2	 * ExpenseService
3	 *
4	 * Service for managing expenses derived from receipts
5	 * Specification: #{#exp1b} - Expenses Derived from Receipts
6	 * Authority: system
7	 * Priority: Critical
8	 *
9	 * Key Principles:
10	 * - Expenses are computed views, not separate database entities
11	 * - Each receipt generates exactly one expense (1:1 mapping)
12	 * - Deleting a receipt automatically removes the expense (CASCADE)
13	 * - Creating a receipt automatically makes it available as an expense
14	 */
15	
16	import type { SupabaseClient } from '@supabase/supabase-js';
17	
18	/**
19	 * Expense data structure derived from receipts
20	 * #{#umf1b} - Extended with matched_transaction_id for unmatched filter
21	 */
22	export interface Expense {
23		receipt_id: string;
24		merchant_name: string;
25		total_amount: number;
26		transaction_date: string;
27		receipt_image_path?: string;
28		category_id: string | null;
29		categorization_source: 'manual' | 'auto' | null;
30		category_name?: string | null;
31		category_color?: string | null;
32		matched_transaction_id: string | null; // #{#umf1b} - Match status for reconciliation
33		currency: string | null; // #{#fcr4a} - Original currency for display
34		exchange_rate_to_cad: number | null; // #{#fcr4a} - Bank of Canada rate for estimated CAD
35	}
36	
37	/**
38	 * Filter options for querying expenses
39	 */
40	export interface ExpenseFilters {
41		startDate?: string;
42		endDate?: string;
43		categoryId?: string;
44		merchantName?: string;
45	}
46	
47	/**
48	 * ExpenseService Class
49	 * Handles all expense-related operations
50	 */
51	export class ExpenseService {
52		private supabase: SupabaseClient;
53	
54		constructor(supabase: SupabaseClient) {
55			this.supabase = supabase;
56		}
57	
58		/**
59		 * Get expenses for a user (derived from receipts)
60		 *
61		 * @param userId - User ID to filter expenses
62		 * @param filters - Optional filters (date range, category, merchant)
63		 * @returns Array of expenses
64		 *
65		 * Specification: #{#exp1b} Requirements 1, 2, 3, 7
66		 */
67		async getExpenses(userId: string, filters?: ExpenseFilters): Promise<Expense[]> {
68			// Requirement: User ID validation
69			if (!userId) {
70				throw new Error('User ID is required');
71			}
72	
73			// Build query: Join receipts with expense_categories and categories
74			// This creates the "computed view" of expenses from receipts
75			// #{#umf1b} - Added matched_transaction_id to support unmatched filter
76			// Don't filter by user_id - let RLS policies handle access based on family membership
77			let query = this.supabase.from('receipts').select(
78				`
79					id,
80					merchant_name,
81					total_amount,
82					transaction_date,
83					receipt_image_path,
84					matched_transaction_id,
85					currency,
86					exchange_rate_to_cad,
87					expense_categories (
88						category_id,
89						categorization_source,
90						categories (
91							name,
92							color
93						)
94					)
95				`
96			);
97	
98			// Apply filters if provided
99			if (filters?.startDate) {
100				query = query.gte('transaction_date', filters.startDate);
101			}
102	
103			if (filters?.endDate) {
104				query = query.lte('transaction_date', filters.endDate);
105			}
106	
107			if (filters?.merchantName) {
108				query = query.ilike('merchant_name', `%${filters.merchantName}%`);
109			}
110	
111			// Default sort: transaction_date descending (newest first)
112			query = query.order('transaction_date', { ascending: false });
113	
114			// Execute query
115			const { data, error } = await query;
116	
117			if (error) {
118				throw new Error(error.message);
119			}
120	
121			// Transform database results into Expense objects
122			// Handle 1:1 mapping: each receipt → one expense
123			// #{#umf1b} - Include matched_transaction_id in transformation
124			const expenses: Expense[] = (data || []).map((receipt: any) => {
125				const expenseCategory = receipt.expense_categories;
126				const category = expenseCategory?.categories;
127	
128				return {
129					receipt_id: receipt.id,
130					merchant_name: receipt.merchant_name,
131					total_amount: receipt.total_amount,
132					transaction_date: receipt.transaction_date,
133					receipt_image_path: receipt.receipt_image_path,
134					category_id: expenseCategory?.category_id || null,
135					categorization_source: expenseCategory?.categorization_source || null,
136					category_name: category?.name || null,
137					category_color: category?.color || null,
138					matched_transaction_id: receipt.matched_transaction_id || null,
139					currency: receipt.currency || null,
140					exchange_rate_to_cad: receipt.exchange_rate_to_cad ?? null
141				};
142			});
143	
144			// Apply category filter after transformation (if needed)
145			// Note: For better performance, this could be moved to the SQL query
146			// but current schema makes it complex due to LEFT JOIN structure
147			let filteredExpenses = expenses;
148			if (filters?.categoryId) {
149				filteredExpenses = expenses.filter((expense) => expense.category_id === filters.categoryId);
150			}
151	
152			return filteredExpenses;
153		}
154	
155		/**
156		 * Assign a category to an expense (receipt)
157		 *
158		 * @param receiptId - Receipt ID to categorize
159		 * @param categoryId - Category ID to assign
160		 * @param source - Source of categorization ('manual' or 'auto')
161		 *
162		 * Specification: #{#exp5b} - Manual Override Precedence
163		 */
164		async assignCategory(
165			receiptId: string,
166			categoryId: string,
167			source: 'manual' | 'auto' = 'manual'
168		): Promise<void> {
169			if (!receiptId) {
170				throw new Error('Receipt ID is required');
171			}
172	
173			if (!categoryId) {
174				throw new Error('Category ID is required');
175			}
176	
177			// Insert or update expense category
178			// Manual assignments always override auto assignments
179			const { error } = await this.supabase.from('expense_categories').upsert(
180				{
181					receipt_id: receiptId,
182					category_id: categoryId,
183					categorization_source: source,
184					updated_at: new Date().toISOString()
185				},
186				{
187					onConflict: 'receipt_id'
188				}
189			);
190	
191			if (error) {
192				throw new Error(error.message);
193			}
194		}
195	
196		/**
197		 * Bulk assign category to multiple expenses
198		 *
199		 * @param receiptIds - Array of receipt IDs
200		 * @param categoryId - Category ID to assign
201		 * @param source - Categorization source ('manual' or 'auto'), defaults to 'manual'
202		 *
203		 * Specification: #{#exp6b} - Bulk Category Assignment
204		 * Updated: #{#vca1a} - Support auto-assignment source
205		 */
206		async bulkAssignCategory(
207			receiptIds: string[],
208			categoryId: string,
209			source: 'manual' | 'auto' = 'manual'
210		): Promise<void> {
211			if (!receiptIds || receiptIds.length === 0) {
212				throw new Error('Receipt IDs are required');
213			}
214	
215			if (!categoryId) {
216				throw new Error('Category ID is required');
217			}
218	
219			// Create batch update records
220			const updates = receiptIds.map((receiptId) => ({
221				receipt_id: receiptId,
222				category_id: categoryId,
223				categorization_source: source,
224				updated_at: new Date().toISOString()
225			}));
226	
227			// Batch upsert
228			const { error } = await this.supabase.from('expense_categories').upsert(updates, {
229				onConflict: 'receipt_id'
230			});
231	
232			if (error) {
233				throw new Error(error.message);
234			}
235		}
236	
237		/**
238		 * Normalize vendor name for pattern matching
239		 *
240		 * @param merchantName - Raw merchant name
241		 * @returns Normalized pattern
242		 *
243		 * Specification: #{#exp4a} - Vendor Normalization
244		 */
245		normalizeVendor(merchantName: string): string {
246			return merchantName
247				.toLowerCase()
248				.trim()
249				.replace(/[^a-z0-9\s]/g, '') // Remove special chars
250				.replace(/\s+/g, ' '); // Normalize whitespace
251		}
252	
253		/**
254		 * Get existing vendor rule for a merchant
255		 *
256		 * @param familyId - Family ID
257		 * @param merchantName - Merchant name to look up
258		 * @returns Vendor rule with category info, or null if not found
259		 *
260		 * Specification: #{#exp5a} - Vendor Rule Management (Family-scoped)
261		 */
262		async getVendorRule(
263			familyId: string,
264			merchantName: string
265		): Promise<{ category_id: string; category_name: string } | null> {
266			if (!familyId || !merchantName) {
267				return null;
268			}
269	
270			const vendorPattern = this.normalizeVendor(merchantName);
271	
272			const { data, error } = await this.supabase
273				.from('vendor_category_rules')
274				.select('category_id, categories(name)')
275				.eq('family_id', familyId)
276				.eq('vendor_pattern', vendorPattern)
277				.single();
278	
279			if (error || !data) {
280				return null;
281			}
282	
283			return {
284				category_id: data.category_id,
285				category_name: (data.categories as any)?.name || 'Unknown'
286			};
287		}
288	
289		/**
290		 * Create vendor category rule
291		 *
292		 * @param familyId - Family ID
293		 * @param merchantName - Merchant name to match
294		 * @param categoryId - Category to assign
295		 *
296		 * Specification: #{#exp4a} - Automatic Category Assignment via Vendor Rules (Family-scoped)
297		 */
298		async createVendorRule(
299			familyId: string,
300			merchantName: string,
301			categoryId: string
302		): Promise<void> {
303			if (!familyId || !merchantName || !categoryId) {
304				throw new Error('Family ID, merchant name, and category ID are required');
305			}
306	
307			const vendorPattern = this.normalizeVendor(merchantName);
308	
309			const { error } = await this.supabase.from('vendor_category_rules').upsert(
310				{
311					family_id: familyId,
312					vendor_pattern: vendorPattern,
313					category_id: categoryId,
314					updated_at: new Date().toISOString()
315				},
316				{
317					onConflict: 'family_id,vendor_pattern'
318				}
319			);
320	
321			if (error) {
322				throw new Error(error.message);
323			}
324		}
